/// BUG 1: base case returns 0; should return 1
pub fn factorial(n: u64) -> u64 {
    if n == 0 {
        return 0;
    }
    n * factorial(n - 1)
}

/// BUG 2: base case returns b (always 0) instead of a
pub fn gcd(a: u64, b: u64) -> u64 {
    if b == 0 {
        return b;
    }
    gcd(b, a % b)
}

/// BUG 3: compares sqrt*sqrt to n+1 instead of n
pub fn is_perfect_square(n: u64) -> bool {
    let sqrt = (n as f64).sqrt() as u64;
    sqrt * sqrt == n + 1
}

